// Original teaching cases. Dependencies are business rules, never inferred from sample rows.
const D=(from,to,kind='full')=>({from,to,kind});
const T=(name,key,attributes,dependencies,foreign={})=>({name,key,attributes,dependencies,foreign});
function example({title,assumptions,name,key,attributes,values,groups,data}){
 const initial=[D(key,values),...groups.map(g=>D(g.key,g.attributes.filter(a=>!g.key.includes(a)&&!g.transitive?.attributes.includes(a)),'partial')),...groups.filter(g=>g.transitive).map(g=>D(g.transitive.key,g.transitive.attributes,'transitive'))];
 const links=Object.fromEntries(groups.flatMap(g=>g.key.map(k=>[k,g.name+'.'+k])));
 const second=[...groups.map(g=>T(g.name,g.key,[...g.key,...g.attributes],[D(g.key,g.attributes.filter(a=>!g.transitive?.attributes.includes(a))),...(g.transitive?[D(g.transitive.key,g.transitive.attributes,'transitive')]:[])])),T(name,key,[...key,...values],[D(key,values)],links)];
 const third=groups.flatMap(g=>g.transitive?[T(g.transitive.name,g.transitive.key,[...g.transitive.key,...g.transitive.attributes],[D(g.transitive.key,g.transitive.attributes)]),T(g.name,g.key,[...g.key,...g.attributes.filter(a=>!g.transitive.attributes.includes(a))],[D(g.key,g.attributes.filter(a=>!g.transitive.attributes.includes(a)))],Object.fromEntries(g.transitive.key.map(k=>[k,g.transitive.name+'.'+k])))]:[T(g.name,g.key,[...g.key,...g.attributes],[D(g.key,g.attributes)])]);
 third.push(T(name,key,[...key,...values],[D(key,values)],links));
 return {title,assumptions,data,stages:{1:{explanation:'All cells are atomic and the stated candidate key identifies one row. The key determines every other attribute, but the lower arrows reveal partial and transitive dependencies. This relation is in 1NF, not 2NF.',tables:[T(name,key,attributes,initial)]},2:{explanation:'Remove partial dependencies into tables for the corresponding key parts. Keep the complete composite key and its own facts in the association. A non-key determinant still appears in one table, so this result is not yet wholly in 3NF.',tables:second},3:{explanation:'Separate each non-key determinant and the attributes it determines. Retain that determinant as a foreign key in the original table. Every non-trivial determinant is now a candidate key under the stated rules; the relations are in 3NF.',tables:third}}};
}
